/** A referenced parent issue must be live and in the same project. */
async function assertValidParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
}

/** An assignee must be a current member of the workspace being changed. */
async function assertAssignableMember(
  orgId: OrgId,
  assigneeId: UserId | null,
): Promise<void> {
  if (assigneeId === null) return;
  const member = await memberRepo.findMember(orgId, assigneeId);
  if (!member) throw new NotFoundError("Member", assigneeId);
}

/** Every label attached to an issue must belong to the same workspace. */
async function assertLabelsInOrg(
  orgId: OrgId,
  labelIds: readonly string[],
): Promise<void> {
  if (labelIds.length === 0) return;
  const found = await labelRepo.listLabelsByIds(
    orgId,
    labelIds as readonly import("@/types/common").LabelId[],
  );
  const foundIds = new Set(found.map((label) => label.id));
  for (const labelId of labelIds) {
    if (!foundIds.has(labelId)) throw new NotFoundError("Label", labelId);
  }
}

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

