/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. Both sources are only ever trusted up
 * to the org's live membership: a client-provided id or a stale/foreign
 * handle is silently dropped rather than notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);

  const verifiedClientProvided = (
    await Promise.all(
      clientProvided.map(async (userId) =>
        (await memberRepo.findMember(orgId, userId)) ? userId : null,
      ),
    )
  ).filter((userId): userId is UserId => userId !== null);

  return [...new Set([...resolved, ...verifiedClientProvided])];
}

